"""Background folder watcher — poll for new media and enqueue jobs."""

from __future__ import annotations

import logging
import threading
import time
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .batch import build_batch_requests, scan_media_files

_log = logging.getLogger("transub_engine.watch")


def _file_key(path: Path) -> str:
    try:
        st = path.stat()
        return f"{path.resolve()}|{int(st.st_mtime_ns)}|{int(st.st_size)}"
    except OSError:
        return str(path.resolve())


@dataclass
class WatchState:
    id: str
    folder: str
    recursive: bool = True
    interval_s: float = 15.0
    extensions: list[str] | None = None
    template: dict[str, Any] = field(default_factory=dict)
    output_dir: str | None = None
    settle_s: float = 2.0
    enabled: bool = True
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    last_scan_at: float | None = None
    enqueued_total: int = 0
    last_error: str | None = None
    last_batch_id: str | None = None
    seen: set[str] = field(default_factory=set)


class WatchManager:
    """Poll-based watchers (no OS FS events — portable on Windows)."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._watches: dict[str, WatchState] = {}
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None

    def start(
        self,
        *,
        folder: str,
        recursive: bool = True,
        interval_s: float = 15.0,
        extensions: list[str] | None = None,
        template: dict[str, Any] | None = None,
        output_dir: str | None = None,
        settle_s: float = 2.0,
        seed_existing: bool = True,
    ) -> WatchState:
        root = Path(folder)
        if not root.is_dir():
            raise FileNotFoundError(f"folder not found: {folder}")
        wid = uuid.uuid4().hex[:10]
        state = WatchState(
            id=wid,
            folder=str(root.resolve()),
            recursive=bool(recursive),
            interval_s=max(3.0, float(interval_s or 15)),
            extensions=list(extensions) if extensions else None,
            template=dict(template or {}),
            output_dir=output_dir,
            settle_s=max(0.0, float(settle_s or 0)),
        )
        if seed_existing:
            # Mark current files as seen so only *new* arrivals enqueue.
            try:
                for path in scan_media_files(
                    state.folder,
                    recursive=state.recursive,
                    extensions=state.extensions,
                    limit=2000,
                ):
                    state.seen.add(_file_key(path))
            except Exception as err:
                _log.warning("watch seed failed: %s", err)
        with self._lock:
            self._watches[wid] = state
            self._ensure_thread_locked()
        return state

    def stop(self, watch_id: str | None = None) -> bool:
        with self._lock:
            if watch_id:
                st = self._watches.pop(watch_id, None)
                return st is not None
            self._watches.clear()
            return True

    def list(self) -> list[dict[str, Any]]:
        with self._lock:
            return [self._public(w) for w in self._watches.values()]

    def get(self, watch_id: str) -> dict[str, Any] | None:
        with self._lock:
            w = self._watches.get(watch_id)
            return self._public(w) if w else None

    def _public(self, w: WatchState) -> dict[str, Any]:
        return {
            "id": w.id,
            "folder": w.folder,
            "recursive": w.recursive,
            "intervalSec": w.interval_s,
            "extensions": w.extensions,
            "template": w.template,
            "outputDir": w.output_dir,
            "settleSec": w.settle_s,
            "enabled": w.enabled,
            "createdAt": w.created_at,
            "updatedAt": w.updated_at,
            "lastScanAt": w.last_scan_at,
            "enqueuedTotal": w.enqueued_total,
            "seenCount": len(w.seen),
            "lastError": w.last_error,
            "lastBatchId": w.last_batch_id,
        }

    def _ensure_thread_locked(self) -> None:
        if self._thread and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, name="transub-watch", daemon=True)
        self._thread.start()

    def _loop(self) -> None:
        while not self._stop.is_set():
            try:
                self._tick()
            except Exception as err:
                _log.exception("watch tick failed: %s", err)
            # Sleep in slices so stop is responsive
            for _ in range(10):
                if self._stop.is_set():
                    break
                time.sleep(0.5)

    def _tick(self) -> None:
        with self._lock:
            watches = list(self._watches.values())
        now = time.time()
        for w in watches:
            if not w.enabled:
                continue
            if w.last_scan_at and (now - w.last_scan_at) < w.interval_s:
                continue
            try:
                self._scan_one(w)
            except Exception as err:
                w.last_error = str(err)
                w.updated_at = time.time()
                _log.warning("watch %s scan error: %s", w.id, err)

    def _scan_one(self, w: WatchState) -> None:
        from .jobs import JOBS

        files = scan_media_files(
            w.folder,
            recursive=w.recursive,
            extensions=w.extensions,
            limit=2000,
        )
        newcomers: list[Path] = []
        for path in files:
            key = _file_key(path)
            if key in w.seen:
                continue
            # Settle: skip files still being written (mtime too recent)
            try:
                age = time.time() - path.stat().st_mtime
                if age < w.settle_s:
                    continue
            except OSError:
                continue
            newcomers.append(path)
            w.seen.add(key)

        w.last_scan_at = time.time()
        w.updated_at = w.last_scan_at
        w.last_error = None
        if not newcomers:
            return

        template = dict(w.template or {})
        if w.output_dir:
            template["outputDir"] = w.output_dir
        bid, reqs = build_batch_requests(
            [str(p) for p in newcomers],
            template=template,
        )
        _, jobs = JOBS.create_batch(reqs, batch_id=bid, run_async=True)
        w.enqueued_total += len(jobs)
        w.last_batch_id = bid
        _log.info(
            "watch %s enqueued %s file(s) batch=%s",
            w.id,
            len(jobs),
            bid,
        )


WATCHES = WatchManager()
